export interface Receipt { id: number; tenant: string; key: string; cents: number }
export class Ledger {
  readonly entries: Receipt[] = [];
  // Idempotency records scoped by tenant, then key. Nested maps avoid
  // collisions between distinct (tenant, key) pairs.
  private readonly records = new Map<string, Map<string, Receipt>>();
  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    // No await before this point: the lookup and the insert below run in one
    // synchronous step, so concurrent calls with the same tenant/key cannot
    // both debit.
    let byKey = this.records.get(tenant);
    if (!byKey) { byKey = new Map(); this.records.set(tenant, byKey); }
    const existing = byKey.get(key);
    if (existing) {
      if (existing.cents !== cents) throw new Error('key conflict');
      return { ...existing };
    }
    const receipt: Receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.entries.push(receipt);
    byKey.set(key, receipt);
    return { ...receipt };
  }
}
EOF
